        'open ar': ['ذمم مدينة مفتوحة', 'Créances Clients'],
        'ar open': ['ذمم مدينة مفتوحة', 'Créances Clients'],
        'gross ar': ['إجمالي الذمم المدينة', 'Créances Brutes'],
        'ar collected': ['المحصل من الذمم', 'Créances Encaissées'],
