        'security deposits': ['تأمينات المستأجرين', 'Dépôts de Garantie'],
        'security deposits held': ['تأمينات محتجزة', 'Dépôts Détenus'],
        'partner pool': ['مجمع الشركاء', 'Pool Associés'],
