        'fit-out & repairs': ['التجهيزات والصيانة', 'Aménagements & Travaux'],
        'venue': ['إيرادات الفرع', 'Recettes Site'],
        'memberships': ['الاشتراكات', 'Abonnements'],
        'memberships paid': ['اشتراكات محصّلة', 'Abonnements Encaissés'],
