    m = trimmed.match(/^POS SHIFT CLOSE & BILL VARIANCE REGISTER\s*\((\d+)\)$/i);
    if (m) return lang === 'ar' ? `سجل إقفال ورديات نقاط البيع وفروقات الفواتير (${m[1]})` : `REGISTRE DE CLÔTURE POS ET ÉCARTS DE CAISSE (${m[1]})`;

    m = trimmed.match(/^30\s*\/\s*60\s*\/\s*90-Day Policy Renewal Queue & Lapsed Policy Tracker\s*\((\d+)\)$/i);
