    m = trimmed.match(/^TOTAL CATALOGUE PRODUCTION\s*\((\d+)\s+FLAGSHIP LINES OF\s+(\d+)\s+PRODUCTS\)$/i);
    if (m) return lang === 'ar' ? `إجمالي إنتاج الدليل (${m[1]} خطاً رئيسياً من أصل ${m[2]} منتجاً)` : `TOTAL PRODUCTION CATALOGUE (${m[1]} LIGNES PHARES SUR ${m[2]} PRODUITS)`;

    m = trimmed.match(/^TOTAL LOAN FACILITIES\s*\(([\d,]+)\)$/i);
    if (m) return lang === 'ar' ? `إجمالي التسهيلات والقروض (${m[1]})` : `TOTAL LIGNES DE PRÊT (${m[1]})`;

    m = trimmed.match(/^TOTAL OPEN LOANS\s*\(([\d,]+)\)$/i);
    if (m) return lang === 'ar' ? `إجمالي القروض المفتوحة (${m[1]})` : `TOTAL PRÊTS OUVERTS (${m[1]})`;

    m = trimmed.match(/^TOTAL PARTNER ACCOUNTS\s*\(([\d,]+)\)$/i);
    if (m) return lang === 'ar' ? `إجمالي حسابات الشركاء (${m[1]})` : `TOTAL COMPTES ASSOCIÉS (${m[1]})`;

    m = trimmed.match(/^NET DRAWER IMPACT\s*\(([\d,]+)\s+CONVERSIONS\s*·\s*VOL\s+(\$[\d.,]+)\)$/i);
    if (m) return lang === 'ar' ? `صافي أثر الصندوق (${m[1]} عملية صرافة · حجم ${m[2]})` : `IMPACT NET CAISSE (${m[1]} OPÉRATIONS · VOL. ${m[2]})`;

    m = trimmed.match(/^Rule\s+(#[A-Z0-9]+)$/i);
    if (m) return lang === 'ar' ? `قاعدة ${m[1]}` : `Règle ${m[1]}`;

