    if (m) return lang === 'ar' ? `زيوت ${m[1]} ل · شحم ${m[2]} كغ` : `Huile ${m[1]} L · Gr. ${m[2]} kg`;

    m = trimmed.match(/^AR\s+([+-]?\$[\d.,kM]+)\s*·\s*Cash Sales\s+([+-]?\$[\d.,kM]+)$/i);
    if (m) return lang === 'ar' ? `ذمم مدينة ${m[1]} · مبيعات نقدية ${m[2]}` : `Créances ${m[1]} · Ventes Comptant ${m[2]}`;

    m = trimmed.match(/^Ext\/Ln\s+([+-]?\$[\d.,kKM]+)\s*·\s*FX\s+([\d,]+)$/i);
    if (m) return lang === 'ar' ? `خارجي/قروض ${m[1]} · صرافة ${m[2]}` : `Ext./Prêts ${m[1]} · Change ${m[2]}`;

    m = trimmed.match(/^Active\s+(\d+)\s*·\s*Absent\s+(\d+)$/i);
