    m = trimmed.match(/^Active fleet\s+([\d,]+)$/i);
    if (m) return lang === 'ar' ? `الأسطول النشط ${m[1]}` : `Flotte active ${m[1]}`;

    m = trimmed.match(/^(\d+)\s+Shelf\s*·\s*(\d+)\s+Outside$/i);
    if (m) return lang === 'ar' ? `${m[1]} مستودع · ${m[2]} خارجي` : `${m[1]} Magasin · ${m[2]} Externe`;

    m = trimmed.match(/^([\d.,]+)\s*L\s*·\s*\+([\d.,]+)h\s+OT$/i);
    if (m) return lang === 'ar' ? `${m[1]} ل · +${m[2]} س إضافي` : `${m[1]} L · +${m[2]}h HS`;

    m = trimmed.match(/^OT\s+\+([\d.,]+)h\s*·\s*(\d+)\s+OT Loads?$/i);
    if (m) return lang === 'ar' ? `إضافي +${m[1]} س · ${m[2]} نقلات إضافي` : `HS +${m[1]}h · ${m[2]} Voyages HS`;

    m = trimmed.match(/^\(([\d.,]+%)\s+(covered|3rd-party)\)$/i);
    if (m) {
      const k = /covered/i.test(m[2]) ? (lang === 'ar' ? 'مغطّى' : 'couvert') : (lang === 'ar' ? 'نقل خارجي' : 'tiers');
      return `(${m[1]} ${k})`;
    }

    m = trimmed.match(/^>(\d+)\s*L\/100km\s+or\s+>(\d+)\s*L\/h$/i);
    if (m) return lang === 'ar' ? `>${m[1]} ل/100كم أو >${m[2]} ل/ساعة` : `>${m[1]} L/100km ou >${m[2]} L/h`;

    m = trimmed.match(/^Cash:\s*([\d.,]+%)\s*\(([^)]+)\)\s*vs\s*Credit:\s*([\d.,]+%)\s*\(([^)]+)\)$/i);
    if (m) return lang === 'ar' ? `نقدي: ${m[1]} (${m[2]}) مقابل ذمم: ${m[3]} (${m[4]})` : `Comptant : ${m[1]} (${m[2]}) vs Crédit : ${m[3]} (${m[4]})`;

    // 8. Additional Ledger / Operational / 360° Inspector / Tooltip Parametric Rules
    m = trimmed.match(/^Loan\s+(\d{4}-\d{2}-\d{2})\s+(.+)$/i);
    if (m) return lang === 'ar' ? `قرض ${m[1]} ${m[2]}` : `Prêt ${m[1]} ${m[2]}`;

    m = trimmed.match(/^CONV\s+(\d{4}-\d{2}-\d{2})\s+(USD to LBP|LBP to USD)\s+(.+)$/i);
    if (m) {
      const dir = /USD to LBP/i.test(m[2]) ? (lang === 'ar' ? 'دولار إلى ليرة' : 'USD vers LBP') : (lang === 'ar' ? 'ليرة إلى دولار' : 'LBP vers USD');
      return lang === 'ar' ? `تحويل ${m[1]} (${dir}) ${m[3]}` : `CONV ${m[1]} (${dir}) ${m[3]}`;
    }
    m = trimmed.match(/^SALE\s+(\d{4}-\d{2}-\d{2})\s+(.+)$/i);
    if (m) return lang === 'ar' ? `مبيع ${m[1]} ${m[2]}` : `VENTE ${m[1]} ${m[2]}`;

    m = trimmed.match(/^EXP\s+(\d{4}-\d{2}-\d{2})\s+(.+)$/i);
