    if (m) return lang === 'ar'
      ? `متبقي الدولار: ${m[1]} · مستحق ل.ل.: ${m[2]} · مدفوع ل.ل.: ${m[3]} · متبقي ل.ل.: ${m[4]}`
      : `Reste USD : ${m[1]} · Acquis LBP : ${m[2]} · Payé LBP : ${m[3]} · Reste LBP : ${m[4]}`;

    m = trimmed.match(/^USD Rem:\s*(\$[\d.,-]+)\s*\|\s*LBP Rem:\s*([\d.,-]+\s*LL)$/i);
