    if (m) {
      const sr = translateSearchList(m[1].trim(), lang);
      if (sr.ok) {
        const dots = m[2] || '';
        return { out: lang === 'ar' ? `تصفية ${sr.out}${dots}` : `Filtrer ${sr.out}${dots}`, ok: true };
      }
    }
    m = trimmed.match(/^Select or type\s+(.+?)(\.\.\.|…)?$/i);
    if (m) {
      const sr = translateSearchList(m[1].trim(), lang);
      const dots = m[2] || '';
      return { out: lang === 'ar' ? `اختر أو اكتب ${sr.out}${dots}` : `Choisir ou saisir ${sr.out}${dots}`, ok: sr.ok };
    }
    m = trimmed.match(/^Enter PIN for\s+(.+)$/i);
    if (m) return { out: lang === 'ar' ? `أدخل الرمز السري لـ ${m[1]}` : `Code PIN pour ${m[1]}`, ok: true };

    m = trimmed.match(/^Welcome back,\s*(.+)$/i);
    if (m) return { out: lang === 'ar' ? `مرحباً بعودتك، ${m[1]}` : `Bon retour, ${m[1]}`, ok: true };

