    if (m) {
      const rest = evalCore(m[2].trim(), lang, depth + 1);
      if (rest.ok) return { out: `RDL-${m[1]} ${rest.out}`, ok: true };
    }

    m = trimmed.match(/^Arrears\s+(\$[\d.,kM]+)$/i);
    if (m) return { out: lang === 'ar' ? `متأخرات ${m[1]}` : `Arriérés ${m[1]}`, ok: true };

