    if (m) return { out: lang === 'ar' ? `مدفوع ${m[1]} من أصل ${m[2]}${m[3]}` : `Payé ${m[1]} sur ${m[2]}${m[3]}`, ok: true };

    m = trimmed.match(/^Claimed\s+(\$[\d.,]+)\s*·\s*Approved\s+(\$[\d.,]+)$/i);
    if (m) return { out: lang === 'ar' ? `المطالب به ${m[1]} · المعتمد ${m[2]}` : `Réclamé ${m[1]} · Agréé ${m[2]}`, ok: true };

    m = trimmed.match(/^Advance\s+([+-]?\$[\d.,]+)$/i);
    if (m) return { out: lang === 'ar' ? `سلفة ${m[1]}` : `Avance ${m[1]}`, ok: true };

    m = trimmed.match(/^(.+?)\s+Cutover Audit$/i);
    if (m) return { out: lang === 'ar' ? `تدقيق فترة الانتقال (${translateMonthTokens(m[1], lang)})` : `Audit de Bascule (${translateMonthTokens(m[1], lang)})`, ok: true };

    m = trimmed.match(/^Bdeir Fleet\s*\((.+)\)$/i);
    if (m) return { out: lang === 'ar' ? `أسطول بدير (${m[1]})` : `Flotte Bdeir (${m[1]})`, ok: true };

    m = trimmed.match(/^WTC Own Trucks\s*\((.+)\)$/i);
    if (m) return { out: lang === 'ar' ? `شاحنات WTC الخاصة (${m[1]})` : `Camions Propres WTC (${m[1]})`, ok: true };

    const cntHit = translateCountNoun(trimmed, lang);
    if (cntHit) return { out: cntHit, ok: true };

